export const examinationSteps=[
 {id:'identity',label:'Confirm patient identity',detail:'Check the patient against the appointment record.',required:true},
 {id:'passport',label:'Review the Patient Passport',detail:'Review recorded allergies, medicines and previous procedures.',required:true},
 {id:'symptoms',label:'Confirm the patient’s answers',detail:'Review the reason for the visit and the questionnaire.',required:true},
 {id:'observations',label:'Record examination observations',detail:'Confirm that the relevant observations have been recorded.',required:false},
 {id:'sample',label:'Collect requested samples',detail:'For an approved blood or urine collection only.',required:false},
 {id:'nextstep',label:'Explain the next step to the patient',detail:'Confirm that the patient knows what happens next.',required:true}
];
export function automaticRoute(r){if(r.category==='Urgent'||r.type==='Prescription'||r.type==='Tests'||r.category==='Medical'&&r.type==='Administrative')return 'Doctor';if(r.category==='Administrative')return 'Administration';if(r.type==='Walk-in')return 'Nurse';const concern=r.answers?.find(([q])=>q==='Main concern')?.[1]||'';return /cold|throat|urinar/i.test(concern)?'Nurse':'Doctor';}
export function ensureExaminations(state){state.examinations??=[];for(const x of state.examinations){if(x.appointmentId&&x.status==='In progress'&&state.appointments.some(a=>a.id===x.appointmentId&&a.status==='Cancelled'))x.status='Cancelled';}for(const r of state.requests){r.route=automaticRoute(r);if(r.route==='Nurse'&&['Pending','Appointment needed'].includes(r.status)&&!state.examinations.some(x=>x.requestId===r.id)){state.examinations.push({id:'exam-'+r.id,patient:r.patient,requestId:r.id,title:r.title,status:'In progress',steps:{},history:[]});}}for(const a of state.appointments.filter(a=>a.status==='Booked'&&a.kind==='Laboratory'&&a.orderId)){if(!state.examinations.some(x=>x.appointmentId===a.id))state.examinations.push({id:'exam-'+a.id,patient:a.patient,requestId:a.orderId,appointmentId:a.id,title:'Sample collection · '+a.title,status:'In progress',steps:{},history:[]});}}
export function nursingTimestamp(value){return value?new Date(value).toLocaleString('en-GB',{timeZone:'Europe/Ljubljana',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'';}
export function nursingRecordHTML(state,person,{icon,escapeHTML:e}){const records=(state.examinations||[]).filter(x=>x.patient===person&&Object.keys(x.steps).length);return `<section class="panel nursing-summary"><div class="panel-head"><div><p class="eyebrow">SHARED EXAMINATION RECORD</p><h2>Steps recorded by the nurse</h2></div>${icon('checkCircle')}</div>${records.length?records.map(x=>`<article class="nursing-record"><div class="status-top"><h3>${e(x.title)}</h3><span class="pill ${x.status==='Completed'?'':'amber'}">${e(x.status)}</span></div><p class="small muted">Nurse Maja Petrič${x.completedAt?' · Finished '+nursingTimestamp(x.completedAt):''}</p>${examinationSteps.filter(step=>x.steps[step.id]).map(step=>{const entry=x.steps[step.id];return `<div class="nursing-summary-step">${icon(entry.value==='Done'?'checkCircle':'clock')}<div><strong>${e(step.label)} · ${e(entry.value)}</strong><small>${e(entry.by)} · ${nursingTimestamp(entry.at)}</small></div></div>`;}).join('')}<p class="small muted">${examinationSteps.length-Object.keys(x.steps).length} steps not yet recorded</p></article>`).join(''):'<p class="empty">No examination steps have been recorded for this patient yet. Saved nurse steps appear here automatically.</p>'}</section>`;}
export function renderNurse(state,{icon,escapeHTML:e,passportHTML}){const active=state.nurseFilter!=='Completed';const exams=state.examinations.filter(x=>active?x.status==='In progress':x.status==='Completed');const exam=exams.find(x=>x.id===state.selectedExam)||exams[0];const admins=state.requests.filter(r=>r.route==='Administration'&&r.status==='Pending');return `<div class="intro"><div><p class="eyebrow">NURSE WORKSPACE · MAJA PETRIČ</p><h1>Record each step, once.</h1><p>Patients arrive here through the automatic workflow. Your examination record is shared with the doctor.</p></div><span class="step-label">${icon('users')} ${exams.length} ${active?'open':'completed'} examinations</span></div><div class="doctor-layout"><section class="panel queue-panel"><div class="panel-head"><h2>Nursing examinations</h2></div><div class="filters"><button class="filter ${active?'active':''}" data-action="nurse-filter" data-value="Open">Open</button><button class="filter ${!active?'active':''}" data-action="nurse-filter" data-value="Completed">Completed</button></div>${exams.map(x=>`<button class="queue-row ${exam?.id===x.id?'selected':''}" data-action="select-exam" data-id="${e(x.id)}"><div class="queue-patient"><strong>${e(state.patients[x.patient].name)}</strong><span class="pill">${Object.keys(x.steps).length}/${examinationSteps.length} recorded</span></div><h3>${e(x.title)}</h3><p>${x.appointmentId?'Approved laboratory appointment':'Automatically assigned to nurse'}</p></button>`).join('')||'<p class="empty">No examinations in this list.</p>'}<div class="record-group"><h3>${icon('file')} Administrative requests</h3>${admins.map(r=>`<article class="admin-task"><strong>${e(state.patients[r.patient].name)}</strong><p>${e(r.title)}</p><button class="btn" data-action="complete-admin" data-id="${e(r.id)}">${icon('check')} Complete request</button></article>`).join('')||'<p class="small muted">No administrative requests pending.</p>'}</div></section><div class="stack" id="request-detail">${exam?examDetail(exam):'<section class="panel"><h2>Select an examination</h2><p class="empty">Nurse-directed patient requests and booked lab collections appear here automatically.</p></section>'}</div></div>`;
 function examDetail(x){const completed=x.status==='Completed';const canFinish=examinationSteps.every(s=>x.steps[s.id]&&((s.required||(x.appointmentId&&s.id==='sample'))?x.steps[s.id].value==='Done':['Done','Not applicable'].includes(x.steps[s.id].value)));const request=state.requests.find(r=>r.id===x.requestId);return `<section class="panel"><div class="panel-head"><div><p class="eyebrow">${e(state.patients[x.patient].name)} · EXAMINATION</p><h2>${e(x.title)}</h2></div><span class="pill ${completed?'':'amber'}">${e(x.status)}</span></div><div class="notice">${icon('passport')}<span>Use the same patient record. Each saved step records who completed it and when.</span></div>${request?`<details class="nurse-answers"><summary>View patient’s selected answers</summary>${request.answers.map(([q,a])=>`<p><strong>${e(q)}</strong><br>${e(a)}</p>`).join('')}</details>`:''}<div class="nurse-checklist">${examinationSteps.map(s=>{const entry=x.steps[s.id];const required=s.required||!!x.appointmentId&&s.id==='sample';return `<article class="nurse-step"><h3>${e(s.label)}${required?'<span class="required-step">Required</span>':''}</h3><p>${e(s.detail)}</p><div class="step-options" role="group" aria-label="${e(s.label)}">${['Done',...(!required?['Not applicable']:[])].map(v=>`<button class="btn ${entry?.value===v?'primary':''}" data-action="exam-step" data-id="${e(x.id)}" data-step="${s.id}" data-value="${v}" aria-pressed="${entry?.value===v}" ${completed?'disabled':''}>${icon(v==='Done'?'check':'x')} ${v}</button>`).join('')}${entry&&!completed?`<button class="btn subtle" data-action="exam-step" data-id="${e(x.id)}" data-step="${s.id}" data-value="clear">Undo step</button>`:''}</div><p class="step-stamp">${entry?e(entry.by)+' · '+nursingTimestamp(entry.at):'Not yet recorded'}</p></article>`;}).join('')}</div>${completed?`<div class="notice">${icon('checkCircle')}<span>Completed by Nurse Maja Petrič · ${nursingTimestamp(x.completedAt)}. This signed demo record is read-only.</span></div>`:`<button class="btn primary full" data-action="finish-exam" data-id="${e(x.id)}" ${!canFinish?'disabled':''}>${icon('checkCircle')} Complete examination record</button><p class="small muted" style="margin-top:10px">Complete every required step and mark optional steps Done or Not applicable.</p>`}${x.history?.length?`<details class="nurse-answers"><summary>Step history · ${x.history.length} updates</summary>${x.history.slice().reverse().map(h=>`<p><strong>${e(examinationSteps.find(s=>s.id===h.step)?.label||h.step)} · ${e(h.value)}</strong><br>${e(h.by)} · ${nursingTimestamp(h.at)}</p>`).join('')}</details>`:''}<p class="warning-note">Illustrative workflow checklist. Completed observations are recorded as steps; this demo does not capture measurements or replace a clinical protocol.</p></section>${passportHTML(x.patient,true)}`;}
}
